<template><div class="page-card"><h2>AI咨询</h2><el-input v-model="prompt" type="textarea" :rows="5" placeholder="请输入你的需求，例如：我喜欢科幻小说，请推荐几本书"/><el-button type="primary" style="margin-top:16px" @click="ask">{{ isAdmin?'获取运营建议':'获取借阅推荐' }}</el-button><el-alert v-if="answer" :title="answer" type="success" style="margin-top:20px" :closable="false"/></div></template>
<script setup>import {ref,computed} from 'vue';import http from '../api/http';const prompt=ref(''),answer=ref('');const isAdmin=computed(()=>JSON.parse(localStorage.getItem('library_user')||'{}').role==='ADMIN');async function ask(){const r=await http.post(isAdmin.value?'/ai/advice':'/ai/recommend',prompt.value,{headers:{'Content-Type':'text/plain'}});answer.value=r.data};</script>
